// Turns an Agent Office notification into a Telegram message. Telegram tasks go back to the chat
// that created them; tasks dropped in the Trello inbox go to the owner's chat. Others send nothing.
const ownerChat = String($env.TELEGRAM_DEFAULT_CHAT_ID ?? '').trim();
const chatFor = (n) => {
  if (n?.source === 'TELEGRAM') {
    return n.externalReference;
  }
  return n?.source === 'TRELLO' ? ownerChat : '';
};
const escape = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

return $input.all()
  .map((item) => item.json.body)
  .filter((n) => chatFor(n))
  .map((n) => {
    const summary = n.summary ? ['', '<b>Summary</b>', escape(n.summary)] : [];
    const templates = {
      TASK_COMPLETED: ['✅ <b>Task completed</b>', '', `Title: ${escape(n.title)}`, `Agent: ${n.agent}`,
        `Review: ${n.review ?? '—'}`, ...summary],
      TASK_FAILED: ['❌ <b>Task failed</b>', '', `Title: ${escape(n.title)}`, `Reason: ${escape(n.reason)}`],
      TASK_BLOCKED: ['⛔ <b>Task blocked</b>', '', `Title: ${escape(n.title)}`, `Reason: ${escape(n.reason)}`,
        '', `Resume it with /retry ${n.taskId}`],
      HUMAN_APPROVAL_REQUESTED: ['🙋 <b>Waiting for your approval</b>', '', `Title: ${escape(n.title)}`,
        `Agent: ${n.agent}`, ...summary],
    };
    const lines = templates[n.event] ?? [`ℹ️ ${escape(n.event)}`, '', `Title: ${escape(n.title)}`];
    lines.push('', `ID: <code>${n.taskId}</code>`);
    if (n.boardUrl) {
      lines.push(`Trello: ${escape(n.boardUrl)}`);
    }
    return { json: { chatId: chatFor(n), text: lines.join('\n') } };
  });
